'use strict';
const fs=require('fs'),path=require('path');const{chromium}=require('playwright');
const BASE=(process.env.P14_BASE_URL||'https://plan-ex.ru/erpv2/').replace(/\/+$/,'/'),U=p=>new URL(p,BASE).href,OUT=path.resolve(process.env.P14_OUT_DIR||'P14_output');fs.mkdirSync(OUT,{recursive:true});const OWNER='p14_owner_260804221827';
function rc(){const e=process.env.P11_CREDENTIALS_B64||'';return e?JSON.parse(Buffer.from(e,'base64').toString('utf8')):[]}function sa(){return rc().find(x=>String(x?.role||'').toUpperCase()==='SUPERADMIN')}
async function lt(b,u,pw){const c=await b.newContext({viewport:{width:1920,height:1080},deviceScaleFactor:1,ignoreHTTPSErrors:true,locale:'ru-RU',timezoneId:'Europe/Moscow'}),p=await c.newPage();let ok=false;try{await p.goto(U('login'),{waitUntil:'domcontentloaded'});await p.locator('input[name="username"],input[name="email"],input[type="text"]').first().fill(u);await p.locator('input[type="password"]').fill(pw);await Promise.all([p.waitForLoadState('domcontentloaded').catch(()=>{}),p.locator('button[type="submit"],input[type="submit"]').first().click()]);await p.waitForTimeout(500);ok=!/\/login(?:[/?#]|$)/i.test(p.url())}catch{}return{ok,c,p}}
function cs(t,v){const a=[...v];for(const m of String(t).matchAll(/[A-Za-z0-9!@#$%^&*()_+\-=]{8,64}/g))a.push(m[0]);return[...new Set(a)].filter(x=>x!==OWNER&&!x.includes('@example.test')&&!/^[a-f0-9]{64}$/i.test(x))}
async function owner(b){const s=sa(),x=await lt(b,s.username,s.password);await x.p.goto(U('superadmin/companies/27/users'),{waitUntil:'domcontentloaded'});const f=x.p.locator('form[action$="/superadmin/companies/27/owner/reset-password"]'),n=x.p.waitForNavigation({waitUntil:'domcontentloaded'});await f.evaluate(z=>HTMLFormElement.prototype.submit.call(z));await n;const v=await x.p.locator('input,textarea,code,pre,[data-password]').evaluateAll(ns=>ns.map(n=>n.value||n.textContent||'').filter(Boolean)),a=cs(await x.p.locator('body').innerText(),v);await x.c.close();for(const q of a){const y=await lt(b,OWNER,q);if(y.ok)return y;await y.c.close()}throw Error('owner unavailable')}
async function set(f,n,v){const x=f.locator(`[name="${n}"]`).first();if(!(await x.count()))return false;const tag=await x.evaluate(e=>e.tagName);if(tag==='SELECT')await x.evaluate((el,val)=>{const o=[...el.options].find(x=>String(x.value)===String(val));if(o){el.value=o.value;el.dispatchEvent(new Event('input',{bubbles:true}));el.dispatchEvent(new Event('change',{bubbles:true}))}},String(v));else await x.fill(String(v));return true}
(async()=>{const r={status:'FAIL',response:null,invalidFields:[],messages:[],tripId:null,finalUrl:null,error:null};let b,o;try{b=await chromium.launch({headless:true});o=await owner(b);const p=o.p;await p.goto(U('company/trips/linear'),{waitUntil:'domcontentloaded'});let row=p.locator('[data-linear-route-id]').filter({hasText:'P14 Тестовый безопасный груз'}).first();if(await row.count()){r.tripId=Number(await row.getAttribute('data-linear-route-id'));r.status='PASS';return}await p.goto(U('company/trips/linear?show_create=1'),{waitUntil:'domcontentloaded'});const f=p.locator('#linear-trip-create-form');await set(f,'route_type','linear');await set(f,'planned_loading_date','07.08.2026');await set(f,'client_id','1');await set(f,'carrier_contractor_id','1');await set(f,'route_executor_id','1');await set(f,'cargo_type_name','P14 Тестовый безопасный груз');await set(f,'customer_payments[0][amount]','120000');await set(f,'customer_payments[0][payment_method]','cashless');await set(f,'customer_payments[0][vat_rate]','');await set(f,'customer_payments[0][condition_type]','prepayment');await set(f,'carrier_payments[0][amount]','85000');await set(f,'carrier_payments[0][payment_method]','cashless');await set(f,'carrier_payments[0][vat_rate]','');await set(f,'carrier_payments[0][condition_type]','after_end');await set(f,'carrier_payments[0][days_count]','5');await set(f,'carrier_payments[0][days_kind]','working');await set(f,'comments','P14 isolated representative trip');r.invalidFields=await f.evaluate(form=>[...form.elements].filter(e=>typeof e.checkValidity==='function'&&!e.checkValidity()).map(e=>({name:e.name,type:e.type,message:e.validationMessage,valueLength:String(e.value||'').length})));const responses=[];p.on('response',async z=>{if(z.url().includes('/company/trips/linear/create')){let body='';try{body=await z.text()}catch{}responses.push({status:z.status(),url:z.url(),body:body.slice(0,2000)})}});const btn=p.locator('button[type="submit"][form="linear-trip-create-form"],#linear-trip-create-form button[type="submit"],button').filter({hasText:/Создать рейс|Сохранить/i}).first();if(await btn.count())await btn.click();else await f.evaluate(x=>x.requestSubmit());await p.waitForTimeout(2500);r.response=responses.at(-1)||null;r.finalUrl=p.url();r.messages=await p.locator('.field-msg,.notice,.alert,.error,.invalid-feedback').evaluateAll(ns=>ns.map(n=>(n.innerText||'').trim()).filter(Boolean));await p.screenshot({path:path.join(OUT,'P14_TRIP_CREATE_RESULT_1920x1080.png'),fullPage:false});await p.goto(U('company/trips/linear'),{waitUntil:'domcontentloaded'});row=p.locator('[data-linear-route-id]').filter({hasText:'P14 Тестовый безопасный груз'}).first();if(await row.count()){r.tripId=Number(await row.getAttribute('data-linear-route-id'));r.status='PASS'}else r.status='FAIL'}catch(e){r.error={name:e?.name||'Error',message:String(e?.message||e).slice(0,500)}}finally{if(o?.c)await o.c.close().catch(()=>{});if(b)await b.close().catch(()=>{});fs.writeFileSync(path.join(OUT,'P14_runtime_result.json'),JSON.stringify(r,null,2));console.log(`P14_TRIP_CREATE=${r.status}`);process.exitCode=r.status==='PASS'?0:1}})();
